package com.bank.serverlesspatterns;

import java.util.*;
import java.util.logging.*;

public class ServerlessPatternsDemo {
    private static final Logger log = Logger.getLogger("ServerlessPatterns");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ServerlessPatternAdvisor advisor = new ServerlessPatternAdvisor();

        List<WorkloadShape> shapes = List.of(
            new WorkloadShape("payment-crud-api", "crud", 1, false),
            new WorkloadShape("payment-workflow", "workflow", 5, false),
            new WorkloadShape("payment-events", "event-fanout", 1, false),
            new WorkloadShape("statement-generation", "async", 2, false),
            new WorkloadShape("nightly-reconciliation", "batch", 40, true));

        for (WorkloadShape s : shapes) {
            log.info(() -> s.name() + " -> " + advisor.recommend(s));
        }
    }
}

// ─── Would be in ServerlessPatternAdvisor.java ───
class ServerlessPatternAdvisor {
    String recommend(WorkloadShape s) {
        // Not a fit: long-running or heavy sustained compute.
        if (s.durationMinutes() > 15 || s.heavyCompute()) {
            return "NOT serverless — use ECS/EKS container (exceeds 15m or heavy sustained compute)";
        }
        return switch (s.type()) {
            case "crud"         -> "API Gateway + Lambda + DynamoDB (simple CRUD, scales to zero)";
            case "workflow"     -> "Step Functions (orchestrate steps, retries, error paths)";
            case "event-fanout" -> "EventBridge (route one event to many consumers, decoupled)";
            case "async"        -> "SQS + Lambda (buffer work, auto-scale consumers, DLQ)";
            default              -> "Review manually — shape unclear";
        };
    }
}

// ─── Would be in WorkloadShape.java ───
class WorkloadShape {
    private final String name;
    private final String type;          // crud, workflow, event-fanout, async, batch
    private final int durationMinutes;
    private final boolean heavyCompute;
    WorkloadShape(String name, String type, int durationMinutes, boolean heavyCompute) {
        this.name = name; this.type = type;
        this.durationMinutes = durationMinutes; this.heavyCompute = heavyCompute;
    }
    String name() { return name; }
    String type() { return type; }
    int durationMinutes() { return durationMinutes; }
    boolean heavyCompute() { return heavyCompute; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
